function strict(s,c=config(s)){return !!c?.worldRules?.enforceLocations;}
function context(s){return s.overworld?.journey||s.overworld?.interaction;}
function pending(s){return context(s)?.pendingEvent;}
function busy(s){return !!(s.overworld?.journey||s.overworld?.interaction);}
