function requirements(v=[]){need(Array.isArray(v)&&v.length<=12,'มีเงื่อนไขได้ไม่เกิน 12 ข้อ (ต้องครบทุกข้อ)');return v.map(c=>{need(c&&['quest','item','skill','stat','proficiency'].includes(c.type),'ชนิดเงื่อนไขไม่ถูกต้อง');if(c.type==='quest'){need(['absent','active','ready','completed','failed'].includes(c.status),'สถานะเงื่อนไขเควสไม่ถูกต้อง');return {type:c.type,id:id(c.id),status:c.status};}if(c.type==='item'){return {type:c.type,...itemRef(c)};}if(c.type==='skill'){need(['skill','spell'].includes(c.kind),'ชนิดวิชาไม่ถูกต้อง');return {type:c.type,kind:c.kind,id:id(c.id)};}if(c.type==='stat'){need(N().stats.includes(c.stat)&&Number.isInteger(c.minimum)&&c.minimum>=1&&c.minimum<=99,'เงื่อนไขค่าสถานะไม่ถูกต้อง');return {type:c.type,stat:c.stat,minimum:c.minimum};}need((Object.hasOwn(N().profs,c.key)||c.key==='dual')&&['D','C','B','A','S'].includes(c.grade),'เงื่อนไขความชำนาญไม่ถูกต้อง');return {type:c.type,key:c.key,grade:c.grade};});}
function itemRef(x){need(kinds.includes(x.kind)&&Number.isInteger(x.quantity)&&x.quantity>=1&&x.quantity<=99,'ของ/จำนวนต้องเป็น 1–99');return {kind:x.kind,id:id(x.id),quantity:x.quantity};}
