function definition(rows,ref){const r=rows.find(r=>r.kind===ref.kind&&r.id===ref.id&&r.enabled!==false);need(r,'ไม่พบรายการที่เปิดใช้ '+ref.id);if(['item','dropItem'].includes(ref.kind))need(rows.filter(x=>['item','dropItem'].includes(x.kind)&&x.name===r.name&&x.enabled!==false).length===1,'ชื่อไอเท็มซ้ำข้ามหมวด ระบุของในกระเป๋าไม่ได้');return r;}
function count(s,rows,ref){const r=definition(rows,ref),v=s.catalogInventory||{items:[],gearStash:[]};return ['item','dropItem'].includes(ref.kind)?v.items.filter(n=>n===r.name).length:v.gearStash.filter(x=>x.refType===ref.kind&&x.name===r.name).length;}
function check(s,conditions,rows=[]){for(const c of requirements(conditions)){if(c.type==='quest'){const q=s.eventJournal?.quests?.find(q=>q.id===c.id);if(c.status==='ready'?!questReady(s,q,rows):(q?.status||'absent')!==c.status)return {ok:false,reason:'ต้องมีเควส '+c.id+' เป็น '+({absent:'ยังไม่รับ',active:'กำลังทำ',ready:'ครบเป้าหมายพร้อมส่ง',completed:'สำเร็จ',failed:'ล้มเหลว'}[c.status])};}else if(c.type==='item'){try{if(count(s,rows,c)<c.quantity)return {ok:false,reason:'ต้องมี '+(definition(rows,c).displayName||definition(rows,c).name)+' ×'+c.quantity};}catch(e){return {ok:false,reason:e.message};}}else if(c.type==='skill'){const owned=s.learned?.includes(c.kind+':'+c.id)||c.id.startsWith('decide-')&&s.character?.skills?.includes(c.id.slice(7));if(!owned)return {ok:false,reason:'ต้องรู้วิชา '+(rows.find(r=>r.kind===c.kind&&r.id===c.id)?.name||c.id)};}else if(c.type==='stat'){if((s.character?.stats?.[c.stat]||0)<c.minimum)return {ok:false,reason:'ต้องมี '+c.stat+' อย่างน้อย '+c.minimum};}else if('DCBAS'.indexOf(s.character?.proficiencyGrades?.[c.key]||'')<'DCBAS'.indexOf(c.grade)||!s.character?.proficiencyGrades?.[c.key])return {ok:false,reason:'ต้องมี '+(N().profs[c.key]||c.key)+' ระดับ '+c.grade};}return {ok:true,reason:''};}
function objectives(v=[],saved=false){need(Array.isArray(v)&&v.length<=8,'เควสมีเป้าหมายได้ไม่เกิน 8 ข้อ');const out=v.map(o=>{need(o&&['kill','item'].includes(o.type)&&Number.isInteger(o.required)&&o.required>=1&&o.required<=999,'เป้าหมายเควสต้องมีจำนวน 1–999');if(o.type==='item')need(kinds.includes(o.kind),'ชนิดของเป้าหมายไม่ถูกต้อง');const x={type:o.type,...(o.type==='kill'?{monsterId:id(o.monsterId)}:{kind:o.kind,id:id(o.id)}),required:o.required};if(o.type==='kill'&&saved){need(Number.isInteger(o.progress??0)&&(o.progress??0)>=0&&(o.progress??0)<=o.required,'ความคืบหน้าเควสผิด');x.progress=o.progress??0;}return x;});need(new Set(out.map(objectiveKey)).size===out.length,'เป้าหมายเควสซ้ำ');return out;}
