function recordVictory(s,e){if(e.status!=='won'||!s.eventJournal?.quests?.some(q=>q.status==='active'&&q.objectives?.some(o=>o.type==='kill')))return;const book=s.eventJournal;book.countedBattles??=[];if(book.countedBattles.includes(e.id))return;need(book.countedBattles.length<10000,'ประวัติการต่อสู้ของเควสเต็ม');book.countedBattles.push(e.id);for(const q of book.quests.filter(q=>q.status==='active'))for(const o of q.objectives||[])if(o.type==='kill')o.progress=Math.min(o.required,(o.progress||0)+e.units.filter(u=>u.side==='enemy'&&u.hp<=0&&u.monsterId===o.monsterId).length);}
