function choiceStatus(s,ev,node,ch,rows){let result=check(s,ch.conditions||[],rows);if(!result.ok)return result;if(s.gold+ch.goldDelta<0)return {ok:false,reason:'เหรียญไม่พอ'};const existing=ch.quest&&s.eventJournal?.quests?.find(q=>q.id===ch.quest.id);if(ch.quest?.status==='completed'&&existing?.objectives?.length&&!questReady(s,existing,rows))return {ok:false,reason:'เป้าหมายเควสยังไม่ครบ'};const key=keyFor(ev,node,ch);if(key&&((s.eventJournal?.claimedChoices||[]).includes(key)||ch.quest?.status==='completed'&&s.eventJournal?.quests.some(q=>q.id===ch.quest.id&&q.status==='completed')))return {ok:false,reason:'รับผลตัวเลือก/เควสนี้แล้ว'};const needed=new Map();for(const ref of ch.consumeItems||[]){const k=ref.kind+':'+ref.id;needed.set(k,{...ref,quantity:(needed.get(k)?.quantity||0)+ref.quantity});}try{for(const ref of needed.values())if(count(s,rows,ref)<ref.quantity)return {ok:false,reason:'ของส่งไม่ครบ: '+definition(rows,ref).name+' ×'+ref.quantity};if(ch.npcAction){if(!npcAllowed(s,ch.npcAction.npcId))return {ok:false,reason:'NPC ไม่ได้อยู่ที่นี่'};const npc=rows.find(r=>r.kind==='npc'&&r.id===ch.npcAction.npcId&&r.enabled!==false);if(!npc)return {ok:false,reason:'ไม่พบ NPC'};if(ch.npcAction.type==='recruit'){if(!npc.recruitable)return {ok:false,reason:'NPC ไม่เปิดให้เข้าทีม'};if(s.catalogParty?.some(p=>p.id===npc.id))return {ok:false,reason:'NPC อยู่ในทีมแล้ว'};const cap=s.adventure?.companion?6:7;if((s.catalogParty?.length||0)>=cap)return {ok:false,reason:'ปาร์ตี้เต็ม'};}if(ch.npcAction.type==='dismiss'&&!s.catalogParty?.some(p=>p.id===npc.id))return {ok:false,reason:'NPC ไม่ได้อยู่ในทีม'};}}catch(e){return {ok:false,reason:e.message};}return {ok:true,reason:''};}
function consume(s,rows,refs){const E=g.DecideCatalogEconomy||(typeof require==='function'?require('./catalog-economy'):null),inv=E.validate(s.catalogInventory);for(const ref of refs){const r=definition(rows,ref);for(let i=0;i<ref.quantity;i++){const source=['item','dropItem'].includes(ref.kind)?inv.items:inv.gearStash,at=source.findIndex(x=>typeof x==='string'?x===r.name:x.refType===ref.kind&&x.name===r.name);need(at>=0,'ของส่งไม่ครบ '+r.name);source.splice(at,1);}}s.catalogInventory=E.validate(inv);}
function npcAction(v){if(!v)return null;need(['shop','craft','recruit','dismiss'].includes(v.type),'การกระทำ NPC ไม่ถูกต้อง');return {type:v.type,npcId:id(v.npcId)};}
function applyNpc(s,rows,p,action){if(!action)return;requireNpc(s,action.npcId);if(['shop','craft'].includes(action.type)){p.service=copy(action);return;}const P=g.DecideCatalogParty||(typeof require==='function'?require('./catalog-party'):null),result=action.type==='recruit'?P.recruit(s,rows,action.npcId,{fromEvent:true}):P.dismiss(s,action.npcId,{fromEvent:true});s.catalogParty=result.catalogParty;if(result.catalogNpcVitals)s.catalogNpcVitals=result.catalogNpcVitals;}
function refs(c,rows){for(const p of c.npcPlacements||[])if(p.enabled){need(rows.some(r=>r.kind==='npc'&&r.id===p.npcId&&r.enabled!==false),'ไม่พบ NPC ที่วาง '+p.npcId);if(p.eventId)need(c.events?.some(e=>e.id===p.eventId&&e.enabled),'อีเวนต์ NPC ไม่ได้เปิดใช้ '+p.eventId);}for(const e of c.events||[]){if(!e.enabled)continue;const checks=[...(e.conditions||[])];for(const n of e.novel?.nodes||[])for(const ch of n.choices){checks.push(...(ch.conditions||[]));for(const item of ch.consumeItems||[])definition(rows,item);for(const o of ch.quest?.objectives||[])need(rows.some(r=>r.kind===(o.type==='kill'?'monster':o.kind)&&r.id===(o.monsterId||o.id)&&r.enabled!==false),'ไม่พบเป้าหมายเควส '+(o.monsterId||o.id));if(ch.npcAction)need(rows.some(r=>r.kind==='npc'&&r.id===ch.npcAction.npcId&&r.enabled!==false),'ไม่พบ NPC ของตัวเลือก');}for(const cond of checks)if(['item','skill'].includes(cond.type))need(rows.some(r=>r.kind===cond.kind&&r.id===cond.id&&r.enabled!==false),'ไม่พบรายการเงื่อนไข '+cond.id);}}
function chapterAt(s,c=config(s)){if(!strict(s,c))return s.adventure?.location||'village';const found=Object.entries(c.worldRules.chapterPlaces||{}).find(([,p])=>p&&W().same(p,location(s,c)));return found?.[0]||'';}
function requireChapter(s,place,c=config(s)){if(strict(s,c))need(chapterAt(s,c)===place,'เดินทางไปสถานที่ของบทนี้บนแผนที่โลกก่อน');}
function chapterTravel(s,to,c=config(s),rows=[]){need(['village','forest','cave'].includes(to),'ไม่พบพื้นที่บท');need(to==='village'||s.adventure?.accepted,'คุยรับงานที่หมู่บ้านก่อน');need(to!=='cave'||s.adventure?.forest,'ยังไม่พบทางเข้าถ้ำ');const target=c.worldRules.chapterPlaces[to];need(target,'ยังไม่ได้ผูกสถานที่บท '+to+' ในหน้าแผนที่');if(W().same(location(s,c),target)){const out=copy(s),A=g.DecideAdventure||(typeof require==='function'?require('./adventure-data'):null);out.adventure=A.validate(out.adventure);out.adventure.location=to;return out;}const route=W().available(s,c).find(r=>W().same(r.from,target)||W().same(r.to,target));need(route,'ไม่มีเส้นทางตรงไปพื้นที่นี้ เดินทางตามเส้นทางบนแผนที่ก่อน');return W().begin(s,c,route.id,'walk',Math.random,rows);}
